package main

import (
	"log"

	"lumen/sync/internal/config"
	"lumen/sync/internal/sync"
	"lumen/sync/pkg/crm"

	"go.uber.org/zap"
)

func main() {
	cfg := config.FromEnv()
	logger, err := zap.NewProduction()
	if err != nil {
		log.Fatal(err)
	}
	defer logger.Sync()

	client := crm.NewClient(cfg.CRMBaseURL, cfg.CRMClientID, cfg.CRMClientSecret, logger)
	w := sync.NewWorker(client, cfg, logger)
	if err := w.RunOnce(); err != nil {
		logger.Fatal("sync cycle failed", zap.Error(err))
	}
}

