package config

import (
	"os"
	"strconv"
)

// Config holds runtime settings for the worker.
type Config struct {
	CRMBaseURL     string
	CRMClientID     string
	CRMClientSecret string
	DatabaseURL    string
	BatchSize      int
	FullSyncBatchSize int
	MaxRetries     int
}

// FromEnv builds Config from environment variables.
func FromEnv() Config {
	return Config{
		CRMBaseURL:     envOr("CRM_BASE_URL", "https://crm.example.com"),
		CRMClientID:     os.Getenv("CRM_CLIENT_ID"),
		CRMClientSecret: os.Getenv("CRM_CLIENT_SECRET"),
		DatabaseURL:    os.Getenv("DATABASE_URL"),
		BatchSize:      envIntOr("BATCH_SIZE", 100),
		FullSyncBatchSize: envIntOr("FULL_SYNC_BATCH_SIZE", 500),
		MaxRetries:     envIntOr("MAX_RETRIES", 5),
	}
}

func envOr(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

func envIntOr(key string, def int) int {
	v := os.Getenv(key)
	if v == "" {
		return def
	}
	n, err := strconv.Atoi(v)
	if err != nil || n <= 0 {
		return def
	}
	return n
}

