package sync

import (
	"database/sql"
	"time"
)

// CursorKey is the sync_state key for the incremental cursor.
const CursorKey = "crm_updated_since"

// LoadCursor reads the stored incremental cursor.
func LoadCursor(db *sql.DB, key string) (string, error) {
	var value string
	err := db.QueryRow(`SELECT value FROM sync_state WHERE key = $1`, key).Scan(&value)
	if err == sql.ErrNoRows {
		return "", nil
	}
	return value, err
}

// saveCursorTx stores the cursor inside the caller's transaction.
func saveCursorTx(tx *sql.Tx, key, value string) error {
	_, err := tx.Exec(`
		INSERT INTO sync_state (key, value, updated_at)
		VALUES ($1, $2, $3)
		ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = EXCLUDED.updated_at`,
		key, value, time.Now().UTC(),
	)
	return err
}

