package sync

import "strings"

// MergeByEmail collapses rows that share an email address, keeping the most
// recently updated one.
func MergeByEmail(rows []Row) []Row {
	latest := map[string]int{}
	out := make([]Row, 0, len(rows))
	for _, r := range rows {
		key := strings.ToLower(strings.TrimSpace(r.Email))
		if i, ok := latest[key]; ok && key != "" {
			if r.UpdatedAt.After(out[i].UpdatedAt) {
				out[i] = r
			}
			continue
		}
		latest[key] = len(out)
		out = append(out, r)
	}
	return out
}

