package sync

import (
	"database/sql"
	"encoding/json"
	"time"
)

// DLQTable is the dead-letter table for exhausted retries.
const DLQTable = "sync_dlq"

// DLQRetentionDays is how long DLQ rows are kept before cold storage.
const DLQRetentionDays = 30

// SendToDLQ stores a failed batch payload for manual replay.
func SendToDLQ(db *sql.DB, payload any, reason string) error {
	raw, err := json.Marshal(payload)
	if err != nil {
		return err
	}
	_, err = db.Exec(
		`INSERT INTO sync_dlq (payload, reason, created_at) VALUES ($1, $2, $3)`,
		string(raw), reason, time.Now().UTC(),
	)
	return err
}

// ReplayDLQ fetches DLQ rows pending manual replay.
func ReplayDLQ(db *sql.DB, limit int) ([]DLQEntry, error) {
	rows, err := db.Query(
		`SELECT id, payload, reason, created_at FROM sync_dlq ORDER BY id LIMIT $1`,
		limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []DLQEntry
	for rows.Next() {
		var e DLQEntry
		if err := rows.Scan(&e.ID, &e.Payload, &e.Reason, &e.CreatedAt); err != nil {
			return nil, err
		}
		out = append(out, e)
	}
	return out, rows.Err()
}

// DLQEntry is one dead-letter row.
type DLQEntry struct {
	ID        int64
	Payload   string
	Reason    string
	CreatedAt time.Time
}

