package sync

// MaskLast4 keeps only the last four characters of s.
func MaskLast4(s string) string {
	if s == "" {
		return ""
	}
	if len(s) <= 4 {
		return "****"
	}
	return "***" + s[len(s)-4:]
}

// MaskNumberPtr masks an optional number pointer for logging.
func MaskNumberPtr(p *string) string {
	if p == nil {
		return ""
	}
	return MaskLast4(*p)
}

