package sync

import (
	"context"

	"lumen/sync/pkg/crm"
)

// Pager iterates CRM pages until next_token is empty.
type Pager struct {
	client *crm.Client
	limit  int
}

// NewPager creates a Pager with the given page limit.
func NewPager(client *crm.Client, limit int) *Pager {
	return &Pager{client: client, limit: limit}
}

// ForEach calls fn for every contact across all pages.
func (p *Pager) ForEach(ctx context.Context, updatedSince, deletedSince string, fn func([]crm.Contact) error) error {
	nextToken := ""
	for {
		page, err := p.client.FetchPage(ctx, updatedSince, deletedSince, nextToken, p.limit)
		if err != nil {
			return err
		}
		if len(page.Contacts) > 0 {
			if err := fn(page.Contacts); err != nil {
				return err
			}
		}
		if page.NextToken == "" {
			return nil
		}
		nextToken = page.NextToken
	}
}

