package sync

import (
	"math"
	"time"
)

// Backoff returns the wait before attempt n (1-based).
func Backoff(base time.Duration, n int) time.Duration {
	if n < 1 {
		n = 1
	}
	d := float64(base) * math.Pow(2, float64(n-1))
	jitter := d * 0.1
	return time.Duration(d + jitter)
}

// RetryThenSkip runs fn up to attempts times with a fixed pause and reports
// whether it eventually succeeded.
func RetryThenSkip(attempts int, pause time.Duration, fn func() error) bool {
	for i := 0; i < attempts; i++ {
		if err := fn(); err == nil {
			return true
		}
		time.Sleep(pause)
	}
	return false
}

