package sync

import (
	"database/sql"
)

// Store writes contact rows into warehouse.contacts.
type Store struct {
	db *sql.DB
}

// NewStore creates a Store over db.
func NewStore(db *sql.DB) *Store {
	return &Store{db: db}
}

// WriteBatchWithCursor upserts rows keyed by crm_id and stores the
// cursor in the same transaction.
func (s *Store) WriteBatchWithCursor(rows []Row, cursorKey, cursorValue string) error {
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()
	for _, r := range rows {
		if _, err := tx.Exec(`
			INSERT INTO warehouse.contacts
				(crm_id, email, country_code, number, name, updated_at, deleted_at)
			VALUES ($1, $2, $3, $4, $5, $6, $7)
			ON CONFLICT (crm_id) DO UPDATE SET
				email = EXCLUDED.email,
				country_code = EXCLUDED.country_code,
				number = EXCLUDED.number,
				name = EXCLUDED.name,
				updated_at = EXCLUDED.updated_at,
				deleted_at = EXCLUDED.deleted_at`,
			r.CRMID, r.Email, r.CountryCode, r.Number, r.Name, r.UpdatedAt.UTC(), r.DeletedAt,
		); err != nil {
			return err
		}
	}
	if err := saveCursorTx(tx, cursorKey, cursorValue); err != nil {
		return err
	}
	return tx.Commit()
}

// UpsertContactPhone writes the single phone column of warehouse.contacts.
func (s *Store) UpsertContactPhone(crmID, phone string) error {
	_, err := s.db.Exec(`UPDATE warehouse.contacts SET phone = $2 WHERE crm_id = $1`, crmID, phone)
	return err
}

