func testServer(t *testing.T, total, limit int) *httptest.Server {
	t.Helper()
	return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/oauth/token" {
			w.Header().Set("Content-Type", "application/json")
			w.Write([]byte(`{"access_token":"tok"}`))
			return
		}
		start := 0
		if tok := r.URL.Query().Get("next_token"); tok != "" {
			n, _ := strconv.Atoi(tok)
			start = n
		}
		end := start + limit
		if end > total {
			end = total
		}
		contacts := make([]map[string]any, 0, end-start)
		for i := start; i < end; i++ {
			contacts = append(contacts, map[string]any{
				"crm_id":     "crm_" + strconv.Itoa(i),
				"email":      "u" + strconv.Itoa(i) + "@test.com",
				"name":       "n" + strconv.Itoa(i),
				"updated_at": "2026-08-10T02:00:00Z",
			})
		}
		next := ""
		if end < total {
			next = strconv.Itoa(end)
		}
		raw, _ := json.Marshal(map[string]any{"contacts": contacts, "next_token": next})
		w.Header().Set("Content-Type", "application/json")
		w.Write(raw)
	}))
}

func TestPagerFetchesAllPages(t *testing.T) {
	srv := testServer(t, 250, 100)
	defer srv.Close()
	client := crm.NewClient(srv.URL, "id", "secret", zap.NewNop())
	p := NewPager(client, 100)
	got := 0
	if err := p.ForEach(context.Background(), "", "", func(c []crm.Contact) error {
		got += len(c)
		return nil
	}); err != nil {
		t.Fatal(err)
	}
	if got != 250 {
		t.Fatalf("expected 250 contacts, got %d", got)
	}
}

func TestToRowsKeysByCRMID(t *testing.T) {
	cc := "+86"
	n1 := "13800138000"
	n2 := "13900139000"
	contacts := []crm.Contact{
		{CRMID: "a", Email: "same@test.com", CountryCode: &cc, Number: &n1, Name: "a", UpdatedAt: "2026-08-10T02:00:00Z"},
		{CRMID: "b", Email: "same@test.com", CountryCode: &cc, Number: &n2, Name: "b", UpdatedAt: "2026-08-10T02:00:00Z"},
	}
	rows, _, err := ToRows(contacts)
	if err != nil {
		t.Fatal(err)
	}
	if len(rows) != 2 {
		t.Fatalf("expected 2 rows, got %d", len(rows))
	}
	if rows[0].CRMID == rows[1].CRMID {
		t.Fatal("rows collapsed on email")
	}
}

func TestMaskLast4(t *testing.T) {
	if got := MaskLast4("13900139000"); got != "***9000" {
		t.Fatalf("unexpected mask %q", got)
	}
}

func TestBackoffIncreases(t *testing.T) {
	if !(Backoff(100000000, 3) > Backoff(100000000, 1)) {
		t.Fatal("backoff should increase")
	}
}

func TestDefaultBatchSize(t *testing.T) {
	t.Setenv("BATCH_SIZE", "")
	cfg := config.FromEnv()
	if cfg.BatchSize != 100 {
		t.Fatalf("expected batch 100, got %d", cfg.BatchSize)
	}
	if cfg.MaxRetries != 5 {
		t.Fatalf("expected retries 5, got %d", cfg.MaxRetries)
	}
}

