package sync

import (
	"strings"
	"time"
)

// Row is the warehouse record written to warehouse.contacts.
type Row struct {
	CRMID       string
	Email       string
	CountryCode *string
	Number      *string
	Name        string
	UpdatedAt   time.Time
	DeletedAt   *time.Time
}

// ParseTimes parses updated_at and deleted_at as UTC ISO8601.
func ParseTimes(updatedAt string, deletedAt *string) (time.Time, *time.Time, error) {
	u, err := time.Parse(time.RFC3339, strings.TrimSpace(updatedAt))
	if err != nil {
		return time.Time{}, nil, err
	}
	u = u.UTC()
	var d *time.Time
	if deletedAt != nil && strings.TrimSpace(*deletedAt) != "" {
		t, err := time.Parse(time.RFC3339, strings.TrimSpace(*deletedAt))
		if err != nil {
			return time.Time{}, nil, err
		}
		utc := t.UTC()
		d = &utc
	}
	return u, d, nil
}

// SplitLegacyPhone converts a legacy single phone string into
// country code and number parts for read compatibility.
func SplitLegacyPhone(phone string) (countryCode *string, number *string) {
	p := strings.TrimSpace(phone)
	if p == "" {
		return nil, nil
	}
	if strings.HasPrefix(p, "+") {
		parts := strings.SplitN(p, " ", 2)
		if len(parts) == 2 {
			cc := strings.TrimSpace(parts[0])
			n := strings.TrimSpace(parts[1])
			return &cc, &n
		}
		cc := "+86"
		rest := strings.TrimPrefix(p, "+86")
		rest = strings.TrimSpace(rest)
		if rest == "" {
			return &cc, nil
		}
		return &cc, &rest
	}
	n := p
	return nil, &n
}

// FillEmailBackfill returns email with backfill applied when empty.
func FillEmailBackfill(email, fallback string) string {
	if strings.TrimSpace(email) != "" {
		return email
	}
	return fallback
}

