package sync

import (
	"context"
	"database/sql"
	"strings"
	"time"

	"lumen/sync/internal/config"
	"lumen/sync/pkg/crm"

	"go.uber.org/zap"
)

// Worker runs incremental and full contact syncs.
type Worker struct {
	client *crm.Client
	cfg    config.Config
	logger *zap.Logger
	db     *sql.DB
	store  *Store
	pager  *Pager
}

// NewWorker builds a Worker. Call OpenDB when a database is configured.
func NewWorker(client *crm.Client, cfg config.Config, logger *zap.Logger) *Worker {
	return &Worker{
		client: client,
		cfg:    cfg,
		logger: logger,
		pager:  NewPager(client, cfg.BatchSize),
	}
}

// OpenDB connects the worker to postgres.
func (w *Worker) OpenDB(driver string) error {
	db, err := sql.Open(driver, w.cfg.DatabaseURL)
	if err != nil {
		return err
	}
	w.db = db
	w.store = NewStore(db)
	return nil
}

// RunOnce performs one incremental sync cycle.
func (w *Worker) RunOnce() error {
	ctx := context.Background()
	cursor, err := w.loadCursor(ctx)
	if err != nil {
		return err
	}
	return w.SyncIncremental(ctx, cursor)
}

// SyncIncremental syncs contacts changed since the cursor.
func (w *Worker) SyncIncremental(ctx context.Context, cursor string) error {
	maxSeen := cursor
	err := w.pager.ForEach(ctx, cursor, cursor, func(contacts []crm.Contact) error {
		rows, max, err := ToRows(contacts)
		if err != nil {
			return err
		}
		if max > maxSeen {
			maxSeen = max
		}
		return w.writeWithRetry(rows, maxSeen)
	})
	return err
}

// SyncFull syncs all contacts, paging until the token is empty.
func (w *Worker) SyncFull(ctx context.Context) error {
	maxSeen := ""
	err := w.pager.ForEach(ctx, "", "", func(contacts []crm.Contact) error {
		rows, max, err := ToRows(contacts)
		if err != nil {
			return err
		}
		if max > maxSeen {
			maxSeen = max
		}
		return w.writeWithRetry(rows, maxSeen)
	})
	return err
}

// ToRows maps CRM contacts to warehouse rows keyed by crm_id.
func ToRows(contacts []crm.Contact) ([]Row, string, error) {
	rows := make([]Row, 0, len(contacts))
	max := ""
	for _, c := range contacts {
		if strings.TrimSpace(c.CRMID) == "" {
			continue
		}
		updated, deleted, err := ParseTimes(c.UpdatedAt, c.DeletedAt)
		if err != nil {
			return nil, "", err
		}
		email := FillEmailBackfill(c.Email, "")
		cc := c.CountryCode
		num := c.Number
		if cc == nil && num == nil && c.Phone != nil {
			cc, num = SplitLegacyPhone(*c.Phone)
		}
		rows = append(rows, Row{
			CRMID:       c.CRMID,
			Email:       email,
			CountryCode: cc,
			Number:      num,
			Name:        c.Name,
			UpdatedAt:   updated,
			DeletedAt:   deleted,
		})
		if c.UpdatedAt > max {
			max = c.UpdatedAt
		}
	}
	return rows, max, nil
}

func (w *Worker) loadCursor(ctx context.Context) (string, error) {
	if w.db == nil {
		return "", nil
	}
	return LoadCursor(w.db, CursorKey)
}

func (w *Worker) writeWithRetry(rows []Row, cursor string) error {
	base := 500 * time.Millisecond
	var err error
	for attempt := 1; attempt <= w.cfg.MaxRetries; attempt++ {
		err = w.storeWrite(rows, cursor)
		if err == nil {
			w.logBatch(len(rows), rows)
			return nil
		}
		if attempt < w.cfg.MaxRetries {
			time.Sleep(Backoff(base, attempt))
		}
	}
	if w.db != nil {
		_ = SendToDLQ(w.db, rows, err.Error())
	}
	w.logger.Error("batch exhausted retries, sent to dlq",
		zap.Int("rows", len(rows)),
		zap.Error(err),
	)
	return err
}

func (w *Worker) storeWrite(rows []Row, cursor string) error {
	if w.store == nil {
		w.logBatch(len(rows), rows)
		return nil
	}
	return w.store.WriteBatchWithCursor(rows, CursorKey, cursor)
}

func (w *Worker) logBatch(n int, rows []Row) {
	masked := ""
	if len(rows) > 0 {
		masked = MaskNumberPtr(rows[0].Number)
	}
	w.logger.Info("batch written",
		zap.Int("rows", n),
		zap.String("number_tail", masked),
	)
}

