package crm

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/url"
	"sync"
	"time"

	"go.uber.org/zap"
)

// Contact is the CRM record in schema v3 shape.
type Contact struct {
	CRMID       string  `json:"crm_id"`
	Email       string  `json:"email"`
	CountryCode *string `json:"country_code"`
	Number      *string `json:"number"`
	Name        string  `json:"name"`
	UpdatedAt   string  `json:"updated_at"`
	DeletedAt   *string `json:"deleted_at"`

	// Phone carries the legacy single phone field from older payloads.
	Phone *string `json:"phone"`
}

// Page is one CRM list response.
type Page struct {
	Contacts  []Contact `json:"contacts"`
	NextToken string    `json:"next_token"`
}

// Client fetches contacts from the CRM API.
type Client struct {
	baseURL      string
	clientID     string
	clientSecret string
	httpClient   *http.Client
	logger       *zap.Logger

	mu          sync.Mutex
	token       string
	tokenExpiry time.Time
}

// NewClient creates a CRM client.
func NewClient(baseURL, clientID, secret string, logger *zap.Logger) *Client {
	return &Client{
		baseURL:      baseURL,
		clientID:     clientID,
		clientSecret: secret,
		httpClient:   &http.Client{Timeout: 15 * time.Second},
		logger:       logger,
	}
}

// FetchPage returns one page of contacts for the given cursor.
func (c *Client) FetchPage(ctx context.Context, updatedSince, deletedSince, nextToken string, limit int) (Page, error) {
	token, err := c.authToken(ctx)
	if err != nil {
		return Page{}, err
	}
	q := url.Values{}
	q.Set("limit", fmt.Sprintf("%d", limit))
	if updatedSince != "" {
		q.Set("updated_since", updatedSince)
	}
	if deletedSince != "" {
		q.Set("deleted_since", deletedSince)
	}
	if nextToken != "" {
		q.Set("next_token", nextToken)
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, c.baseURL+"/crm/contacts?"+q.Encode(), nil)
	if err != nil {
		return Page{}, err
	}
	req.Header.Set("Authorization", "Bearer "+token)
	resp, err := c.httpClient.Do(req)
	if err != nil {
		return Page{}, err
	}
	defer resp.Body.Close()
	if resp.StatusCode == http.StatusTooManyRequests || resp.StatusCode >= 500 {
		return Page{}, &ThrottleError{Status: resp.StatusCode}
	}
	if resp.StatusCode != http.StatusOK {
		return Page{}, fmt.Errorf("crm contacts status %d", resp.StatusCode)
	}
	var p Page
	if err := json.NewDecoder(resp.Body).Decode(&p); err != nil {
		return Page{}, err
	}
	return p, nil
}

// ThrottleError signals a retryable CRM response.
type ThrottleError struct {
	Status int
}

func (e *ThrottleError) Error() string {
	return fmt.Sprintf("crm throttled status %d", e.Status)
}
